// === PHẦN 2: TYPESCRIPT TENANT QUOTA & GRACEFUL DOWNGRADE MIDDLEWARE ===
export type SaaSPlanTier = 'starter' | 'growth' | 'enterprise';

export interface TenantBudgetPolicy {
  tenantId: string;
  plan: SaaSPlanTier;
  monthlySpendUsd: number;
  monthlyCapUsd: number; // vd: Starter $22, Growth $38 để giữ biên lãi > 75%
}

export function selectFinOpsModelTier(
  policy: TenantBudgetPolicy,
  complexity: 'simple_faq' | 'crm_tool_call' | 'deep_escalation',
  notifyZaloOps: (msg: string) => Promise<void>
): { modelAlias: string; maxOutputTokens: number; degraded: boolean } {
  const usageRatio = policy.monthlySpendUsd / policy.monthlyCapUsd;

  if (usageRatio >= 0.8 && usageRatio < 1.0) {
    void notifyZaloOps(`[FinOps SoftCap] Tenant ${policy.tenantId} (${policy.plan}) đạt ${(usageRatio * 100).toFixed(1)}% hạn mức AI tháng.`);
  }

  // Hard Cap 100%: Không trả lỗi 429 làm rớt khách Zalo OA, ép hạ tầng sang tier1-router
  if (usageRatio >= 1.0) {
    return { modelAlias: 'tier1-router', maxOutputTokens: 450, degraded: true };
  }

  if (complexity === 'simple_faq') return { modelAlias: 'tier1-router', maxOutputTokens: 350, degraded: false };
  if (complexity === 'deep_escalation' && policy.plan !== 'starter') {
    return { modelAlias: 'tier3-escalation', maxOutputTokens: 2000, degraded: false };
  }
  return { modelAlias: 'tier2-workhorse', maxOutputTokens: 900, degraded: false };
}

export async function invokeWithLeadAttribution(
  litellmBaseUrl: string,
  tenantVirtualKey: string,
  decision: ReturnType<typeof selectFinOpsModelTier>,
  leadId: string,
  messages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>
) {
  const res = await fetch(`${litellmBaseUrl}/v1/chat/completions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${tenantVirtualKey}` },
    body: JSON.stringify({
      model: decision.modelAlias,
      max_tokens: decision.maxOutputTokens,
      messages,
      metadata: { generation_name: 'zalo_cskh_turn', trace_user_id: leadId, tags: [`degraded:${decision.degraded}`] },
    }),
  });
  if (!res.ok) throw new Error(`AI Gateway error ${res.status}`);
  return res.json();
}
